# area: dunder_dispatch
# hypothesis: len() and iter() look up dunders on the type, so an instance-assigned __len__ and a __getattr__ fallback are ignored for those calls and both checkers should flag them.
from typing import reveal_type


class Bag:
    def __init__(self) -> None:
        self.__len__ = lambda: 7

    def __getattr__(self, name: str) -> int:
        return 99


def probe(bag: Bag) -> None:
    try:
        print(len(bag))  # expect-error
    except TypeError:
        print('len ignores instance __len__')
    try:
        print(iter(bag))  # expect-error
    except TypeError:
        print('iter ignores __getattr__')


b = Bag()
print(b.__len__())
print(b.anything)
reveal_type(b.anything)
probe(b)
